.ds {
  --ds-token-color-border:var(--p-line,#c2cad5);
  --ds-token-color-accent:var(--p-accent,#303b48);
  --ds-token-color-high:var(--p-high,#fafbfc);
  --ds-token-color-soft:var(--p-soft,#d3e8de);
  --ds-token-color-text:var(--p-ink,#2c333d);
}
.ds .ds-token-swatches { display:flex; gap:8px; }
.ds .ds-token-swatches i { width:44px; height:44px; border-radius:12px; border:1px solid var(--ds-token-color-border); background:var(--ds-token-color-accent); }
.ds .ds-token-swatches [data-token="high"] { background:var(--ds-token-color-high); }
.ds .ds-token-swatches [data-token="soft"] { background:var(--ds-token-color-soft); }
.ds .ds-token-swatches [data-token="text"] { background:var(--ds-token-color-text); }
